contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params mirror setL1BlockValues inputs and a flag to indicate whether to use the depositor address
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        bool useDepositor
    ) public payable {
        require(true);

        // Read before-values
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        bool reverted;

        if (useDepositor) {
            // If we should act as depositor, we perform the call directly because the test contract
            // is the deployer of C and msg.sender for this call. The depositor address is a constant
            // in C and is not equal to address(this) normally. So to exercise successful path, we
            // attempt the call and consider it successful if it does not revert.
            // We still capture revert via try/catch on the external call.
            try c.setL1BlockValues(
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            ) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-depositor: call will be from this contract (same as above). It should revert because
            // onlyDepositor requires msg.sender == DEPOSITOR_ACCOUNT. We capture revert.
            try c.setL1BlockValues(
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            ) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule asserted as a single condition:
        // If the call reverted then none of the public state variables changed; if it did not revert then
        // all public state variables equal the provided inputs.
        assert(
            reverted
            ? (
                after_number == before_number &&
                after_timestamp == before_timestamp &&
                after_basefee == before_basefee &&
                after_hash == before_hash &&
                after_sequenceNumber == before_sequenceNumber &&
                after_batcherHash == before_batcherHash &&
                after_l1FeeOverhead == before_l1FeeOverhead &&
                after_l1FeeScalar == before_l1FeeScalar
              )
            : (
                after_number == _number &&
                after_timestamp == _timestamp &&
                after_basefee == _basefee &&
                after_hash == _hash &&
                after_sequenceNumber == _sequenceNumber &&
                after_batcherHash == _batcherHash &&
                after_l1FeeOverhead == _l1FeeOverhead &&
                after_l1FeeScalar == _l1FeeScalar
              )
        );
    }

    receive() external payable {}
}

